<?php
declare(strict_types=1);
require __DIR__ . '/../app/bootstrap.php';
require_login();
$u=current_user();
if (($u['role_code']??'')==='CUSTOMER') { http_response_code(403); exit('Forbidden'); }
function sp(string $title):void{$u=current_user();?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> - MSP ITSM</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/app.css" rel="stylesheet"></head><body><nav class="navbar navbar-dark bg-primary"><div class="container-fluid"><a class="navbar-brand" href="index.php?page=dashboard">MSP ITSM</a><span class="text-white"><?=e($u['full_name'])?> · <a class="text-white" href="index.php?page=logout">Logout</a></span></div></nav><main class="container-fluid p-4"><?php foreach(flashes() as [$t,$m]):?><div class="alert alert-<?=e($t)?>"><?=e($m)?></div><?php endforeach;?><h2><?=e($title)?></h2><?php}
function se():void{?></main></body></html><?php}
$action=(string)get('action','list');
if($action==='save'){verify_csrf();$id=(int)post('id',0);$code=strtoupper(trim((string)post('code','')));$name=trim((string)post('name',''));$description=trim((string)post('description',''));$active=(post('is_active','1')==='1')?1:0;if(!preg_match('/^[A-Z0-9][A-Z0-9._-]{1,49}$/',$code)){flash('danger','Service Code không hợp lệ.');redirect('service.php?action=form'.($id?'&id='.$id:''));}if(mb_strlen($name)<2||mb_strlen($name)>150){flash('danger','Tên Service phải từ 2 đến 150 ký tự.');redirect('service.php?action=form'.($id?'&id='.$id:''));}try{if($id){$q=$db->prepare('UPDATE services SET name=?,description=?,is_active=? WHERE id=?');$q->execute([$name,$description?:null,$active,$id]);audit($db,(int)$u['id'],'UPDATE','SERVICE',$id);}else{$q=$db->prepare('INSERT INTO services(code,name,description,is_active) VALUES(?,?,?,?)');$q->execute([$code,$name,$description?:null,$active]);$id=(int)$db->lastInsertId();audit($db,(int)$u['id'],'CREATE','SERVICE',$id);}flash('success','Đã lưu Service.');}catch(PDOException $e){if((int)($e->errorInfo[1]??0)===1062)flash('danger','Service Code đã tồn tại.');else throw $e;}redirect('service.php?action=view&id='.$id);}
if($action==='toggle'){verify_csrf();$id=(int)get('id',0);$q=$db->prepare('UPDATE services SET is_active=IF(is_active=1,0,1) WHERE id=?');$q->execute([$id]);if($q->rowCount()===0){http_response_code(404);exit('Service not found');}audit($db,(int)$u['id'],'STATUS_CHANGE','SERVICE',$id);redirect('service.php?action=view&id='.$id);}
if($action==='form'){$id=(int)get('id',0);$s=['id'=>0,'code'=>'','name'=>'','description'=>'','is_active'=>1];if($id){$q=$db->prepare('SELECT * FROM services WHERE id=?');$q->execute([$id]);$s=$q->fetch()?:null;if(!$s){http_response_code(404);exit('Service not found');}}sp($id?'Edit Service':'Create Service');?><form method="post" action="service.php?action=save" class="card shadow-sm border-0 mt-3"><div class="card-body"><?=csrf_field()?><input type="hidden" name="id" value="<?=e((string)$s['id'])?>"><div class="row g-3"><div class="col-md-4"><label class="form-label">Service Code *</label><input class="form-control" name="code" required maxlength="50" value="<?=e($s['code'])?>" <?=$id?'readonly':''?>></div><div class="col-md-8"><label class="form-label">Service Name *</label><input class="form-control" name="name" required maxlength="150" value="<?=e($s['name'])?>"></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="4"><?=e($s['description']??'')?></textarea></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="is_active"><option value="1" <?=$s['is_active']?'selected':''?>>ACTIVE</option><option value="0" <?=!$s['is_active']?'selected':''?>>INACTIVE</option></select></div></div></div><div class="card-footer bg-white"><button class="btn btn-primary">Save Service</button> <a class="btn btn-outline-secondary" href="service.php">Cancel</a></div></form><?php se();exit;}
if($action==='view'){$id=(int)get('id',0);$q=$db->prepare('SELECT * FROM services WHERE id=?');$q->execute([$id]);$s=$q->fetch();if(!$s){http_response_code(404);exit('Service not found');}$q=$db->prepare("SELECT COUNT(*) FROM contract_services cs JOIN contracts c ON c.id=cs.contract_id WHERE cs.service_id=? AND c.status IN ('ACTIVE','EXPIRING')");$q->execute([$id]);$contracts=(int)$q->fetchColumn();$q=$db->prepare("SELECT COUNT(*) FROM tickets WHERE service_id=? AND status<>'CLOSED'");$q->execute([$id]);$tickets=(int)$q->fetchColumn();sp('Service · '.$s['name']);?><div class="d-flex justify-content-between mt-3 mb-4"><div><div class="text-muted"><?=e($s['code'])?></div><h3><?=e($s['name'])?></h3></div><div><a class="btn btn-outline-primary" href="service.php?action=form&id=<?=$id?>">Edit</a> <form class="d-inline" method="post" action="service.php?action=toggle&id=<?=$id?>"><?=csrf_field()?><button class="btn btn-outline-warning"><?=$s['is_active']?'Deactivate':'Activate'?></button></form></div></div><div class="row g-3"><div class="col-md-4"><div class="kpi"><span>Status</span><b><?=$s['is_active']?'ACTIVE':'INACTIVE'?></b></div></div><div class="col-md-4"><div class="kpi"><span>Active Contracts</span><b><?=$contracts?></b></div></div><div class="col-md-4"><div class="kpi"><span>Open Tickets</span><b><?=$tickets?></b></div></div></div><div class="card shadow-sm border-0 mt-4"><div class="card-header bg-white fw-bold">Description</div><div class="card-body"><?=nl2br(e($s['description']??''))?:'<span class="text-muted">No description</span>'?></div></div><?php se();exit;}
$qstr=trim((string)get('q',''));$status=(string)get('status','');$w=[];$p=[];if($qstr!==''){$w[]='(s.code LIKE ? OR s.name LIKE ? OR s.description LIKE ?)';$like="%$qstr%";$p=[$like,$like,$like];}if(in_array($status,['ACTIVE','INACTIVE'],true)){$w[]='s.is_active=?';$p[]=$status==='ACTIVE'?1:0;}$sql="SELECT s.*,(SELECT COUNT(*) FROM contract_services cs JOIN contracts c ON c.id=cs.contract_id WHERE cs.service_id=s.id AND c.status IN ('ACTIVE','EXPIRING')) contract_count,(SELECT COUNT(*) FROM tickets t WHERE t.service_id=s.id AND t.status<>'CLOSED') open_tickets FROM services s".($w?' WHERE '.implode(' AND ',$w):'').' ORDER BY s.name';$q=$db->prepare($sql);$q->execute($p);$rows=$q->fetchAll();sp('Service Management');?><div class="d-flex justify-content-between align-items-center mt-3 mb-3"><div class="text-muted">Service Catalog · Contracts · Tickets</div><a class="btn btn-primary" href="service.php?action=form">+ New Service</a></div><form class="row g-2 mb-3"><input type="hidden" name="action" value="list"><div class="col-md-5"><input class="form-control" name="q" placeholder="Code / Name / Description" value="<?=e($qstr)?>"></div><div class="col-md-3"><select class="form-select" name="status"><option value="">All status</option><option value="ACTIVE" <?=$status==='ACTIVE'?'selected':''?>>ACTIVE</option><option value="INACTIVE" <?=$status==='INACTIVE'?'selected':''?>>INACTIVE</option></select></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Filter</button></div></form><div class="card shadow-sm border-0"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Code</th><th>Service</th><th>Description</th><th>Active Contracts</th><th>Open Tickets</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="service.php?action=view&id=<?=$r['id']?>"><?=e($r['code'])?></a></td><td><?=e($r['name'])?></td><td class="text-muted"><?=e(mb_strimwidth((string)($r['description']??''),0,80,'…'))?></td><td><?=$r['contract_count']?></td><td><?=$r['open_tickets']?></td><td><span class="badge text-bg-<?=$r['is_active']?'success':'secondary'?>"><?=$r['is_active']?'ACTIVE':'INACTIVE'?></span></td><td><a class="btn btn-sm btn-outline-primary" href="service.php?action=view&id=<?=$r['id']?>">View</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="text-center text-muted py-4">No services found</td></tr><?php endif;?></tbody></table></div></div><?php se();
